// Normalize an uploaded PDF CV into the shared agent input shape.
const t = $('Telegram Trigger').item.json;
const text = $input.item.json.text || '';
return {
  json: {
    message_text: text,
    existing_cv: {}
  }
};

// Brand-new CV: build purely from the user's message, no existing data.
const t = $('Telegram Trigger').item.json;
return {
  json: {
    message_text: (t.message && t.message.text) || '',
    existing_cv: {}
  }
};

// Update path: merge the new message into the user's existing stored CV.
const t = $('Telegram Trigger').item.json;
const existing = $input.item.json || {};
return {
  json: {
    message_text: (t.message && t.message.text) || '',
    existing_cv: existing
  }
};

// Pull the structured CV from the AI agent output and identity from the trigger
const cv = $input.item.json.output || {};
const trigger = $('Telegram Trigger').item.json;
const msg = trigger.message || {};

// Escape HTML-sensitive characters so CV text can never break the layout
const esc = (s) => (s == null ? '' : String(s)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;'));

const item = {
  chat_id: (msg.chat && msg.chat.id) || '',
  telegram_username: (msg.from && msg.from.username) || '',
  full_name: cv.full_name || '',
  job_title: cv.job_title || '',
  email: cv.email || '',
  phone: cv.phone || '',
  location: cv.location || '',
  summary: cv.summary || '',
  skills: cv.skills || '',
  experience: cv.experience || '',
  education: cv.education || '',
};

// 1. Clean & Format Name (Prevents awkward line breaks)
const formattedName = esc(item.full_name || 'Your Name').toUpperCase();

// 2. Smart Skill Parsing (Handles commas, semicolons, and colons)
let skillsArray = [];
if (item.skills) {
  skillsArray = item.skills
    .split(/[,;:]+/) // Splits by comma, semicolon, or colon
    .map(s => s.trim())
    .filter(s => s.length > 0 && !s.toLowerCase().includes('skills'));
}

const skillsHTML = skillsArray.length > 0
  ? skillsArray.map(skill => `<span class="skill-tag">${esc(skill)}</span>`).join('')
  : (item.skills ? `<span class="skill-tag">${esc(item.skills)}</span>` : '');

// 3. Build HTML Document
const htmlContent = `
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <style>
    /* Print Sizing - Prevents Right Margin Cut-Off */
    @page {
      size: A4 portrait;
      margin: 0;
    }
    * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }
    body {
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Arial, sans-serif;
      color: #334155;
      background-color: #ffffff;
      line-height: 1.5;
      font-size: 12px;
      width: 100%;
      -webkit-print-color-adjust: exact;
    }

    /* Container Grid */
    .cv-container {
      display: grid;
      grid-template-columns: 210px 1fr;
      min-height: 297mm; /* Standard A4 Height */
      width: 210mm;
      box-sizing: border-box;
    }

    /* Left Sidebar */
    .sidebar {
      background-color: #f8fafc;
      padding: 30px 20px;
      border-right: 1px solid #e2e8f0;
      display: flex;
      flex-direction: column;
      gap: 20px;
    }

    .name-box {
      border-bottom: 2.5px solid #2563eb;
      padding-bottom: 12px;
    }

    .name {
      font-size: 18px;
      font-weight: 800;
      color: #0f172a;
      line-height: 1.3;
      word-wrap: break-word;
      letter-spacing: 0.5px;
    }

    .job-title {
      font-size: 11px;
      font-weight: 700;
      color: #2563eb;
      text-transform: uppercase;
      margin-top: 6px;
      letter-spacing: 0.5px;
    }

    .sidebar-heading {
      font-size: 10px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 1px;
      color: #0f172a;
      margin-bottom: 8px;
      border-bottom: 1px solid #cbd5e1;
      padding-bottom: 3px;
    }

    .contact-block {
      margin-bottom: 8px;
      word-break: break-all;
    }

    .contact-label {
      font-size: 9px;
      font-weight: 700;
      color: #64748b;
      text-transform: uppercase;
    }

    .contact-value {
      font-size: 11px;
      color: #334155;
    }

    /* Skill Badges */
    .skills-flex {
      display: flex;
      flex-wrap: wrap;
      gap: 5px;
    }

    .skill-tag {
      background-color: #eff6ff;
      color: #1d4ed8;
      border: 1px solid #bfdbfe;
      font-size: 10px;
      font-weight: 600;
      padding: 3px 7px;
      border-radius: 4px;
      display: inline-block;
    }

    /* Right Main Content */
    .main-content {
      padding: 30px 28px;
      display: flex;
      flex-direction: column;
      gap: 22px;
      overflow: hidden; /* Prevents overflow clipping */
    }

    .section-title {
      font-size: 12px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 1px;
      color: #0f172a;
      border-bottom: 2px solid #0f172a;
      padding-bottom: 4px;
      margin-bottom: 10px;
    }

    .text-block {
      font-size: 11.5px;
      color: #334155;
      line-height: 1.6;
      white-space: pre-line;
      word-wrap: break-word;
    }
  </style>
</head>
<body>

  <div class="cv-container">
    <!-- Sidebar -->
    <aside class="sidebar">
      <div class="name-box">
        <h1 class="name">${formattedName}</h1>
        <div class="job-title">${esc(item.job_title)}</div>
      </div>

      <!-- Contact -->
      <div>
        <div class="sidebar-heading">Contact</div>
        ${item.email ? `<div class="contact-block"><div class="contact-label">Email</div><div class="contact-value">${esc(item.email)}</div></div>` : ''}
        ${item.phone ? `<div class="contact-block"><div class="contact-label">Phone</div><div class="contact-value">${esc(item.phone)}</div></div>` : ''}
        ${item.location ? `<div class="contact-block"><div class="contact-label">Location</div><div class="contact-value">${esc(item.location)}</div></div>` : ''}
        ${item.telegram_username ? `<div class="contact-block"><div class="contact-label">Telegram</div><div class="contact-value">@${esc(item.telegram_username.replace('@', ''))}</div></div>` : ''}
      </div>

      <!-- Skills -->
      ${skillsHTML ? `
      <div>
        <div class="sidebar-heading">Skills</div>
        <div class="skills-flex">${skillsHTML}</div>
      </div>` : ''}

      <!-- Education -->
      ${item.education ? `
      <div>
        <div class="sidebar-heading">Education</div>
        <div class="text-block" style="font-size: 11px;">${esc(item.education)}</div>
      </div>` : ''}
    </aside>

    <!-- Main Content -->
    <main class="main-content">
      ${item.summary ? `
      <section>
        <h2 class="section-title">Professional Summary</h2>
        <p class="text-block">${esc(item.summary)}</p>
      </section>` : ''}

      ${item.experience ? `
      <section>
        <h2 class="section-title">Work Experience</h2>
        <div class="text-block">${esc(item.experience)}</div>
      </section>` : ''}
    </main>
  </div>

</body>
</html>
`;

return {
  json: {
    ...item,
    html: htmlContent
  }
};
